class Solution {
  private int[] parent;

  private int find(int x) {
    while (parent[x] != x) {
      parent[x] = parent[parent[x]];
      x = parent[x];
    }
    return x;
  }

  private int components(int n, int[][] edges, int t) {
    for (int i = 0; i < n; i++) parent[i] = i;
    int comps = n;
    for (int[] e : edges) {
      if (e[2] <= t) continue;
      int a = find(e[0]), b = find(e[1]);
      if (a != b) {
        parent[a] = b;
        comps--;
      }
    }
    return comps;
  }

  public int minTime(int n, int[][] edges, int k) {
    parent = new int[n];
    int lo = 0, hi = 0;
    for (int[] e : edges) hi = Math.max(hi, e[2]);
    while (lo < hi) {
      int mid = (lo + hi) >>> 1;
      if (components(n, edges, mid) >= k) hi = mid;
      else lo = mid + 1;
    }
    return lo;
  }
}
